class FakeConfigParser:
    def __init__(self):
        self.values = {
            ("settings", "username"): "alice",
        }
        self.sections = {
            "settings": [
                ("username", "alice"),
                ("user.email", "alice@example.com"),
                ("port", "8080"),
            ]
        }

    def get(self, section, key):
        try:
            return self.values[(section, key)]
        except KeyError:
            raise configparser.NoOptionError(key, section)

    def items(self, section):
        return self.sections[section]

lookup.cp = FakeConfigParser()

assert lookup.get_value("username", "settings", "", False) == "alice"
assert lookup.get_value("missing", "settings", "fallback", False) == "fallback"
assert lookup.get_value("user\\..*", "settings", "", True) == [
    "alice@example.com"
]
assert lookup.get_value("^port$", "settings", "", True) == ["8080"]
